import { ChangeDetectorRef, Component, ElementRef, ViewChild, inject } from '@angular/core';
import { AbstractControl, FormBuilder, ReactiveFormsModule, ValidationErrors, Validators } from '@angular/forms';

type StepId = 'basic' | 'address' | 'company' | 'summary';

// Validators.required accepts a value made only of spaces.
function requiredText(control: AbstractControl): ValidationErrors | null {
  return String(control.value).trim() ? null : { required: true };
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [ReactiveFormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export default class AppComponent {
  private fb = inject(FormBuilder).nonNullable;
  private changeDetector = inject(ChangeDetectorRef);

  @ViewChild('stepTitle') stepTitle!: ElementRef<HTMLElement>;
  @ViewChild('restartButton') restartButton?: ElementRef<HTMLElement>;

  readonly titles: Record<StepId, string> = {
    basic: 'Basic info',
    address: 'Address',
    company: 'Company',
    summary: 'Summary'
  };

  // The required controls on each step, in the order they appear. An input's id is its path with a dash.
  private readonly stepFields: Record<StepId, string[]> = {
    basic: ['basic.name', 'basic.email'],
    address: ['address.street', 'address.city', 'address.country'],
    company: ['company.name'],
    summary: []
  };

  // The nested groups keep every value while the step template changes.
  form: any = this.fb.group({
    basic: this.fb.group({
      name: ['', requiredText],
      email: ['', [requiredText, Validators.pattern(/\S+@\S+\.\S+/)]]
    }),
    address: this.fb.group({
      street: ['', requiredText],
      city: ['', requiredText],
      country: ['', requiredText],
      postalCode: ['']
    }),
    company: this.fb.group({
      isCompany: [false],
      name: ['', requiredText]
    })
  });

  stepId: StepId = 'basic';
  showErrors = false;
  editing = false;
  submitted = false;

  // Everything about the steps reads this list, so the company step needs no special cases.
  get steps(): StepId[] {
    return this.form.get('company.isCompany').value
      ? ['basic', 'address', 'company', 'summary']
      : ['basic', 'address', 'summary'];
  }

  get stepIndex(): number {
    return this.steps.indexOf(this.stepId);
  }

  get trimmedName(): string {
    return this.form.get('basic.name').value.trim();
  }

  showError(path: string): boolean {
    return this.showErrors && this.form.get(path).invalid;
  }

  next(): void {
    const invalid = this.firstInvalid(this.stepId);
    if (invalid) {
      this.showErrors = true;
      document.getElementById(invalid.replace('.', '-'))?.focus();
      return;
    }

    if (!this.editing) {
      this.goTo(this.steps[this.stepIndex + 1]);
      return;
    }

    // Turning on the company step while editing adds a field nobody has filled in yet.
    const unfinished = this.steps.find(step => this.firstInvalid(step));
    if (!unfinished) this.editing = false;
    this.goTo(unfinished ?? 'summary');
  }

  prev(): void {
    this.editing = false;
    this.goTo(this.steps[this.stepIndex - 1]);
  }

  edit(step: StepId): void {
    this.editing = true;
    this.goTo(step);
  }

  submit(): void {
    this.submitted = true;
    this.changeDetector.detectChanges();
    this.restartButton?.nativeElement.focus();
  }

  restart(): void {
    this.form.reset();
    this.editing = false;
    this.submitted = false;
    this.goTo('basic');
  }

  private firstInvalid(step: StepId): string | undefined {
    return this.stepFields[step].find(path => this.form.get(path).invalid);
  }

  private goTo(step: StepId): void {
    this.stepId = step;
    this.showErrors = false;
    // Angular updates the page after this handler ends, and focus needs the new title now.
    this.changeDetector.detectChanges();
    this.stepTitle.nativeElement.focus();
  }
}

export { AppComponent };

